    return dict(sorted(dct.items(), key=lambda item: item[0]))

if sort == "descending":
    return dict(sorted(dct.items(), key=lambda item: item[0], reverse=True))

raise ValueError(f"Unknown sorting order: {sort}")

"""Rotate the input image by 90 degrees in the plane specified by axes. The rotation is performed in the counter-clockwise direction for positive factor values.

:param img: np.ndarray. The input image to be rotated.
:param factor: int. The number of 90 degree rotations to be applied.
:return: np.ndarray. The rotated image.
"""
factor = factor % 4
if factor == 0:
    return img
elif factor == 1:
    return np.rot90(img, axes=(0, 1))
elif factor == 2:
    return np.rot90(img, axes=(0, 1), k=2)
elif factor == 3:
    return np.rot90(img, axes=(0, 1), k=3)

