"""Convert the input argument to a min-max tuple. If the input is a scalar, it returns a tuple with the first element as the offset - value and the second element as the offset + value. If the input is a tuple, it returns the value + offset (broadcasted).

:param param: scalar, tuple or list of 2+ elements. Input value.
If value is scalar, return value would be (offset - value, offset + value).
If value is tuple, return value would be value + offset (broadcasted).
:param low: Second element of tuple can be passed as an optional argument.
:param bias: An offset factor added to each element.
:return: tuple. The min-max tuple of the input argument.
"""
if isinstance(param, (tuple, list)):
    if len(param) == 2:
        if low is not None:
            param = (low, param[1])
        if bias is not None:
            param = (param[0] + bias, param[1] + bias)
        return param
    else:
        raise ValueError("Param should be a scalar or a tuple/list of length 2")
else:
    if low is not None:
        param = (low, param)
    if bias is not None:
        param = (param + bias, param + bias)
    return param

"""This function replays the saved augmentations on the input data and returns the augmented data.

:param saved_augmentations: Dict. A dictionary containing the saved augmentations.
:param **kwargs: Any. Additional keyword arguments to be passed to the augmentations.
:return: Dict. The augmented data after replaying the saved augmentations.
"""
if not saved_augmentations:
    raise ValueError("Saved augmentations cannot be empty.")

if not isinstance(saved_augmentations, dict):
    raise ValueError("Saved augmentations must be a dictionary.")

if not all(isinstance(value, dict) for value in saved_augmentations.values()):
    raise ValueError("Saved augmentations must be a dictionary of dictionaries.")

if not all(isinstance(key, str) for key in saved_augmentations.keys()):
    raise ValueError("Saved augmentations keys must be strings.")

if not all(isinstance(value, dict) for value in saved_augmentations.values()):
    raise ValueException("Saved augmentations values must be dictionaries.")

if not all(isinstance(key, str) for key in value.keys() for value in saved_augmentations.values()):
    raise ValueError("Saved augmentations values keys must be strings.")

if not all(isinstance(value, (int, float, str, list, tuple, dict)) for value in value.values() for value in saved_augmentations.values()):
    raise ValueError("Saved augmentations values must be int, float, str, list, tuple, or dict.")

if not all(isinstance(value, (int, float, str, list, tuple, dict)) for value in kwargs.values()):
    raise ValueError("Additional keyword arguments must be int, float, str, list, tuple, or dict.")

augmentations = {}
for key, value in saved_augmentations.items():
    augmentations[key] = getattr(augmentations, value["name"])(**value["params"])

return augmentati

