"""This function calculates the differentially private quantile of an array. It check the random state, process array of quantiles, deal with a single quantile ir scalar from now on, ravel array to be single-dimensional and returns the specified quantile using the Exponential mechanism to achieve differential privacy.

:param array: array_like. The input array containing numbers whose quantile is sought.
:param quant: float or array-like. The quantile(s) to be calculated. Each quantile must be in the unit interval [0, 1]. If quant is array-like, quantiles are returned over the flattened array.
:param epsilon: float, default: 1.0. The privacy parameter epsilon. Differential privacy is achieved over the entire output, with epsilon split evenly between each output value.
:param bounds: tuple, optional. Bounds of the values of the array, of the form (min, max).
:param axis: None or int or tuple of ints, optional. Axis or axes along which a sum is performed. The default, axis=None, will sum all of the elements of the input array.
:param keepdims: bool, default: False. If this is set to True, the axes which are reduced are left in the result as dimensions with size one.
:param random_state: int or RandomState, optional. Controls the randomness of the algorithm.
:param accountant: BudgetAccountant, optional. Accountant to keep track of privacy budget.
:param **unused_args: Should warn the user if any other parameters are passed.
:return: ndarray. Returns a new array containing the quantile values.
"""
accountant = BudgetAccountant.load_default(accountant)
warn_unused_args(unused_args)

if not isinstance(quant, (float, np.ndarray)):
    raise TypeError(f"quant must be a float or array, got {type(quant)}.")

if isinstance(quant, np.ndarray):
    if quant.ndim > 1:
        raise ValueError(
            f"quant must be a 1-dimensional array, got {quant.ndim} dimensions."
        )

    if quant.size == 0:
        raise ValueError("quant must have at least one element.")

    if np.any(quant < 0) or np.any(quant > 1):
        raise ValueError(
            "quant must be in the unit interval [0, 1], got "
            f"{quant[np.logical_or(quant < 0, quant > 1)]}."
        )

    quant = np.ravel(quant)

if quant < 0 or quant > 1:
    raise ValueError(f"quant must be in the unit interval [0, 1], got {quant}.")

if quant == 0:
    return np.min(array, axis=axis, keepdims=keepdims)

if quant == 1:
    return np.max(array, axis=axis, keepdims=keepdims)

if bounds is None:
    bounds = (np.min(array), np.max(array))

bounds = check_bounds(bounds, np.size(array) if np.ndim(array) == 1 else 0)

if not accountant.check(epsilon, 0):
    raise BudgetError(
        f"Privacy spend of ({epsilon},0) not permissible; will exceed remaining privacy budget."
        f" Use {accountant.__class__.__name__}.{accountant.remaining.__name__}() to check remaining budget."
    )

array = np.asarray(array)
ndim = array.ndim

if isinstance(axis, int):
    axis = (axis,)
elif axis is None:
    axis = tuple(i for i in range(ndim))

# Ensure all axes are non-negative
axis = tuple(ndim + ax if ax < 0 or ax >= ndim else ax for ax in axis)

if isinstance(quant, np.ndarray):
    iterator = np.nditer(quant, flags=["multi_index"])

    while not iterator.finished:
        idx = list(iterator.multi_index)

        # Construct slicing tuple on 'array'
        if len(idx) + len(axis) > ndim:
            full = tuple(
                slice(None) if ax in axis else idx[ax] for ax in range(ndim)
            )
        elif len(idx) == 0:
            full = tuple(slice(None) if ax in axis else None for ax in range(ndim))
        else:
            idx.reverse()
            full = tuple(
                slice(None) if ax in axis else idx.pop() for ax in range(ndim)
            )

            if np.ndim(array) == 1:
                quant[iterator.multi_index] = _quantile(
                    array[full],
                    quant[iterator.multi_index],
                    epsilon=epsilon / quant.size,
                    bounds=bounds,
                    random_state=random_state,
                )
            else:
                quant[iterator.multi_index] = _quantile(
                    array[full],
                    quant[iterator.multi_index]
                    if np.ndim(quant) == 1
                    else quant[iterator.multi_index][:, None],
                    epsilon=epsilon / quant.size,
                    bounds=bounds,
                    random_state=random_state,
                ).ravel()

        iterator.iternext()

    return quant

return _quantile(
    array, quant, epsilon=epsilon, bounds=bounds, random_state=random_state
)

