    attrs = match.group(2)
    content = match.group(3)
    if tag == "b":
        entities.append(MessageEntityBold(match.start(), len(content)))
    elif tag == "i":
        entities.append(MessageEntityItalic(match.start(), len(content)))
    elif tag == "u":
        entities.append(MessageEntityUnderline(match.start(), len(content)))
    elif tag == "s":
        entities.append(MessageEntityStrike(match.start(), len(content)))
    elif tag == "code":
        entities.append(MessageEntityCode(match.start(), len(content)))
    elif tag == "pre":
        entities.append(MessageEntityPre(match.start(), len(content)))
    elif tag == "a":
        url = re.search(r'href="([^"]+)"', attrs)
        if url:
            entities.append(MessageEntityUrl(match.start(), len(content), url.group(1)))
    elif tag == "text":
        text += content
    else:
        text += content
return text, entiti

