:return: No return values.
"""
if name is None:
    name = receiver.__name__
if sender is None:
    sender = self.sender
if name in self.receivers:
    if sender in self.receivers[name]:
        raise ValueError("Receiver already connected")
    self.receivers[name][sender] = receiver
else:
    self.receivers[name] = {sender: receiver}

