    return autogen_context.opts.get("render_check_constraint", None)(
        constraint, autogen_context, namespace_metadata
    )

if constraint.parent_type is not None:
    return None

if constraint.parameters:
    return "CHECK (%s)" % (
        ", ".join(
            "%s %s" % (param.name, param.type.compile(autogen_context.dialect))
            for param in constraint.parameters
        )
    )
else:
    return "CHECK (%s)" % (constraint.expression)

