    return [(p, v) for i, v in enumerate(root) for p in research(v, query, reraise)]
elif isinstance(root, dict):
    return [(p, v) for k, v in root.items() for p in research(v, query, reraise)]
elif isinstance(root, set):
    return [(p, v) for v in root for p in research(v, query, reraise)]
else:
    try:
        if query(None, None, root):
            return [(None, root)]
    except Exception as e:
        if reraise:
            raise
return []

