"""This function determines the type of a file based on its content. It checks the file's XML structure and content types to identify if it is a Word document, Excel spreadsheet, PowerPoint presentation, or none of these.

:param filename: String. The name of the file to be checked.
:return: Integer. One of the DOCTYPE_* constants indicating the type of the file.
"""
if not os.path.isfile(filename):
    raise IOError("File not found: %s" % filename)

# Check the file's XML structure
with open(filename, "rb") as f:
    content = f.read(1024)

if content.startswith(b"PK\x03\x04"):
    # The file is a ZIP archive
    with zipfile.ZipFile(filename, "r") as zf:
        content_types = zf.read("[Content_Types].xml")
        if b"<Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/>" in content_types:
            return DOCTYPE_OFFICE_DOCUMENT
        elif b"<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>" in content_types:
            return DOCTYPE_OFFICE_DOCUMENT
        elif b"<Default Extension="xlsx" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"/>" in content_types:
            return DOCTYPE_OFFICE_SPREADSHEET
        elif b"<Default Extension="pptx" ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation"/>" in content_types:
            return DOCTYPE_OFFICE_PRESENTATION
        else:
            return DOCTYPE_UNKNOWN
else:
    # The file is not a ZIP archive
    return DOCTYPE_UNKNOWN

