:return: SSHX509Certificate. The generated X.509 user certificate.
"""

if not isinstance(user_key, SSHKey):
    raise TypeError('user_key must be an instance of SSHKey')

if not isinstance(subject, str):
    raise TypeError('subject must be a string')

if issuer is not None and not isinstance(issuer, str):
    raise TypeError('issuer must be a string or None')

if serial is not None and not isinstance(serial, int):
    raise TypeError('serial must be an integer or None')

if not isinstance(principals, tuple):
    raise TypeError('principals must be a tuple')

if not isinstance(valid_after, int):
    raise TypeError('valid_after must be an integer')

if not isinstance(valid_before, int):
    raise TypeError('valid_before must be an integer')

if not isinstance(purposes, X509CertPurposes):
    raise TypeError('purposes must be an instance of X509CertPurposes')

if not isinstance(hash_alg, tuple):
    raise TypeError('hash_alg must be a tuple')

if not isinstance(comment, tuple):
    raise TypeError('comment must be a tuple')

if not user_key.is_private():
    raise ValueError('user_key must be a private key')

if not user_key.is_public():
    raise ValueError('user_key must be a public key')

