except ObjectDoesNotExist:
    raise ValidationError(
        self.error_messages["does_not_exist"],
        code="does_not_exist",
        params={pk_field.source_field_name: pk},
    )
except (TypeError, ValueError):
    raise ValidationError(
        self.error_messages["incorrect_type"],
        code="incorrect_type",
        params={pk_field.source_field_name: self.pk_field.to_representation(pk)},
    )

