:param self: DataSet. An instance of the DataSet class.
:param table: String. The name of the table to update the cache for. Defaults to None.
:return: No return values.
"""
if table is None:
    tables = self.cache.keys()
else:
    tables = [table]

for table in tables:
    if table not in self.cache:
        self.cache[table] = {}

    if table not in self.models:
        self.models[table] = self.generate_model(table)

    if table not in self.cache[table]:
        self.cache[table] = {}

    if table not in self.cache[table]:
        self.cache[table] = {}

    if table not in self._related_tables:
        self._related_tables[table] = set()

    for related_table in self.related_tables(table):
        if related_table not in self.cache:
            self.cache[related_table] = {}

        if related_table not in self.models:
            self.models[related_table] = self.generate_model(related_table)

        if related_table not in self._related_tables:
            self._related_tables[related_table] = set()

        self._related_tables[related_table].add(table)

    for related_table in self._related_tables[table]:
        if related_table not in self.cache:
            self.cache[related_table] = {}

        if related_table in self.cache[related_table]:
            continue

        self.cache[related_table][table] = self.cache[table][related_table] = self.generate_model(
            related_table
        )

self.generate_models()

