    else:
        return notes.int_to_note(notes.note_to_int(note) + 2)
elif interval[0] == "3":
    if interval[1] == "#":
        return notes.augment(notes.augment(notes.augment(note)))
    elif interval[1] == "b":
        return notes.diminish(notes.diminish(notes.diminish(note)))
    else:
        return notes.int_to_note(notes.note_to_int(note) + 3)
elif interval[0] == "4":
