        return notes.augment(notes.augment(notes.augment(notes.augment(note))))
    elif interval[1] == "b":
        return notes.diminish(notes.diminish(notes.diminish((notes.diminish(note)))))
    else:
        return notes.int_to_note(notes.note_to_int(note) + 4)
elif interval[0] == "5":
    if interval[1] == "#":
        return notes.augment(notes.augment(notes.augment(notes.diminish(note))))
    elif interval[1] == "b":
        return notes.diminish(notes.diminish(notes))
    else:
        return notes.int_to_note(notes.note_to_int(note) + 5)
elif interval[0] == "6":
    if interval[1] == "#":
        return notes.augment(notes.augment(notes.diminish(notes.diminish(note))))
    elif interval[1] == "b":
