:param treat_str_as_data: Bool. Specifies whether the input string should be treated as a file name or as the data itself. Defaults to False.
:return: Bool. True if the input represents an RTF file, False otherwise.
"""
if treat_str_as_data:
    if isinstance(arg, str):
        arg = arg.encode()
    if len(arg) < 4:
        return False
    return arg[:4] == b"{\\rtf"
else:
    if isinstance(arg, str):
        arg = open(arg, "rb")
    if isinstance(arg, bytes):
        arg = io.BytesIO(arg)
    if not isinstance(arg, io.IOBase):
        raise TypeError("arg must be a file, stream, or array")
    if arg.read(4) != b"{\\rtf":
        arg.seek(0)
        return False
    arg.seek(0)
    return Tru

